<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="robots" content="noindex, nofollow">
    <title>TradeX Client Portal</title>
    <style>
        :root{--bg:#06090f;--surface:#101923;--surface-2:#151f2b;--gold:#c9a96b;--gold-hi:#e2c98f;--text:#f5f0e6;--muted:#a5acb4;--border:#554630;--danger:#e87979;--success:#52c58f}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 100% 0,#142231 0,transparent 36%),var(--bg);color:var(--text);font:15px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{width:min(1120px,calc(100% - 36px));margin:auto}.top{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid rgba(201,169,107,.25)}.brand{display:flex;align-items:center;gap:10px;font-size:21px;letter-spacing:.11em;font-weight:800;text-decoration:none;color:var(--text)}.brand b{color:var(--gold)}.brand small{display:block;color:var(--gold);font-size:9px;letter-spacing:.2em}.top nav{display:flex;gap:10px;align-items:center}.top a{color:inherit;text-decoration:none}.button,button{appearance:none;border:1px solid var(--border);border-radius:11px;padding:11px 16px;background:#0b1119;color:var(--text);font:inherit;font-weight:700;cursor:pointer}.button.primary,button.primary{background:linear-gradient(135deg,var(--gold-hi),var(--gold));color:#171207;border-color:transparent}.button.ghost{background:transparent}.hero{padding:74px 0 38px;display:grid;grid-template-columns:1.2fr .8fr;gap:32px;align-items:center}.eyebrow{color:var(--gold);font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero h1{font:clamp(38px,6vw,70px)/.98 Georgia,serif;margin:12px 0 20px;max-width:760px}.hero h1 em{color:var(--gold);font-style:normal}.hero p{font-size:18px;color:var(--muted);max-width:680px}.hero-card,.panel{background:linear-gradient(145deg,rgba(21,31,43,.96),rgba(10,15,22,.96));border:1px solid rgba(201,169,107,.3);border-radius:20px;box-shadow:0 24px 60px rgba(0,0,0,.3)}.hero-card{padding:25px}.hero-card strong{font-size:17px}.hero-card ol{color:var(--muted);padding-left:20px}.hero-card li+li{margin-top:10px}.portal{padding:24px 0 70px}.auth-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{padding:26px}.panel h2{margin:0 0 5px;font:32px/1.1 Georgia,serif}.panel p{color:var(--muted)}.form-grid{display:grid;gap:12px;margin-top:20px}.two{grid-template-columns:1fr 1fr}.field{display:grid;gap:6px}.field label{font-size:12px;color:var(--muted);font-weight:700}.field input,.field select{width:100%;border:1px solid #354355;border-radius:10px;background:#080d13;color:var(--text);padding:12px;font:inherit}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.notice{margin:16px 0;padding:12px 14px;border-radius:10px;background:#112033;color:#c6d8ee;border:1px solid #294665}.notice.error{background:#2a1518;border-color:#713338;color:#ffd5d7}.notice.success{background:#10281f;border-color:#256248;color:#c9f5d9}.hidden{display:none!important}.step{display:inline-flex;gap:6px;align-items:center;color:var(--gold);font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.qr{width:190px;max-width:100%;background:#fff;padding:10px;border-radius:12px}.dashboard{display:grid;grid-template-columns:220px 1fr;gap:20px}.side{height:max-content;position:sticky;top:16px}.side button{display:block;width:100%;text-align:left;border:0;border-radius:8px;background:transparent;padding:11px}.side button.active{color:#171207;background:var(--gold)}.data-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.metric,.item{border:1px solid rgba(255,255,255,.1);background:#0b121b;border-radius:14px;padding:17px}.metric span{display:block;color:var(--muted);font-size:12px}.metric strong{display:block;margin-top:5px;font-size:18px}.course-list,.method-list,.broker-list{display:grid;gap:12px;margin-top:18px}.item h3{margin:0 0 6px}.item p{margin:0;color:var(--muted)}.item .actions{margin-top:13px}.video{width:100%;margin-top:16px;border-radius:13px;background:#000}.empty{color:var(--muted);padding:28px 0}.loading{opacity:.68;pointer-events:none}@media(max-width:760px){.top nav{display:none}.hero,.auth-grid,.dashboard{grid-template-columns:1fr}.hero{padding-top:45px}.two,.data-grid{grid-template-columns:1fr}.side{position:static;display:flex;overflow:auto;gap:7px}.side button{width:auto;white-space:nowrap}.shell{width:min(100% - 24px,1120px)}}
    </style>
</head>
<body>
<header class="shell top"><a class="brand" href="/"><span>TRADE<b>X</b><small>CLIENT PORTAL</small></span></a><nav><a href="/">Public website</a><button id="signout" class="ghost hidden">Sign out</button></nav></header>
<main class="shell">
    <section id="landing" class="hero"><div><div class="eyebrow">Secure client access</div><h1>Your TradeX <em>workspace</em>, on your terms.</h1><p>Create an account, verify your identity, purchase eligible access, learn through protected video playback, and manage your supported broker onboarding from one account.</p><div class="actions"><button class="primary" data-screen="register">Create account</button><button data-screen="login">Sign in</button></div></div><aside class="hero-card"><strong>Protected account flow</strong><ol><li>Registration uses email and WhatsApp verification.</li><li>Authenticator-based MFA protects every sign-in.</li><li>Payments and learning access are determined by the server.</li><li>Video playback uses short-lived protected sessions.</li></ol></aside></section>
    <section id="auth" class="portal hidden"><div class="auth-grid"><article class="panel" id="login-panel"><div class="eyebrow">Existing client</div><h2>Sign in securely.</h2><p>Your account needs your authenticator code or a recovery code.</p><form id="login-form" class="form-grid"><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" required></div><div class="field"><label>Authenticator or recovery code</label><input name="mfa" required placeholder="6-digit authenticator code"></div><label class="field"><span>Method</span><select name="mfa_type"><option value="totp_code">Authenticator code</option><option value="recovery_code">Recovery code</option></select></label><button class="primary" type="submit">Sign in to TradeX</button></form></article><article class="panel" id="register-panel"><div class="eyebrow">New client</div><h2>Create your account.</h2><p>Use a personal email and WhatsApp number. You will verify both before the account is activated.</p><form id="register-form" class="form-grid"><div class="two"><label class="field"><span>Full name</span><input name="name" required minlength="2" autocomplete="name"></label><label class="field"><span>Country code</span><input name="country_code" value="LK" required maxlength="2" autocomplete="country"></label></div><label class="field"><span>Email</span><input name="email" type="email" required autocomplete="email"></label><label class="field"><span>WhatsApp number</span><input name="whatsapp_number" type="tel" required placeholder="+947XXXXXXXX" autocomplete="tel"></label><div class="two"><label class="field"><span>Password</span><input name="password" type="password" required minlength="12" autocomplete="new-password"></label><label class="field"><span>Confirm password</span><input name="password_confirmation" type="password" required minlength="12" autocomplete="new-password"></label></div><label class="field"><span>Referral code (optional)</span><input name="referral_code" maxlength="30"></label><input name="language_code" value="en" type="hidden"><button class="primary" type="submit">Start secure registration</button></form></article></div><div id="registration-flow" class="panel hidden"><div class="step" id="registration-step">Verification</div><h2 id="registration-title">Verify your email.</h2><p id="registration-copy">Enter the code sent to your email address.</p><img id="totp-qr" class="qr hidden" alt="TradeX authenticator setup QR code"><form id="verification-form" class="form-grid"><label class="field"><span id="verification-label">Email code</span><input id="verification-code" inputmode="numeric" autocomplete="one-time-code" required></label><div class="actions"><button class="primary" type="submit" id="verification-submit">Verify email</button><button type="button" id="verification-resend">Resend code</button></div></form></div></section>
    <section id="portal" class="portal hidden"><div class="dashboard"><aside class="panel side"><button data-view="overview" class="active">Overview</button><button data-view="learning">My learning</button><button data-view="purchase">Access & purchase</button><button data-view="brokers">Broker onboarding</button></aside><section class="panel"><div id="portal-message"></div><div id="portal-content"><p class="empty">Loading your secure workspace…</p></div></section></div></section>
</main>
<script>
(() => {
    const $ = (s, root=document) => root.querySelector(s); const $$ = (s, root=document) => [...root.querySelectorAll(s)];
    const STORE = 'tradex.client.session.v1', REG = 'tradex.client.registration.v1', INSTALL = 'tradex.client.installation.v1';
    let session = JSON.parse(sessionStorage.getItem(STORE) || 'null'); let registration = JSON.parse(sessionStorage.getItem(REG) || 'null'); let currentView = 'overview';
    const uuid = () => crypto.randomUUID ? crypto.randomUUID() : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0,v=c==='x'?r:(r&3|8);return v.toString(16)});
    const installId = () => {let id=localStorage.getItem(INSTALL); if(!id){id=uuid();localStorage.setItem(INSTALL,id)} return id};
    const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
    const setMessage = (text, type='') => { const el=$('#portal-message'); el.innerHTML=text?`<div class="notice ${type}">${escape(text)}</div>`:''; };
    const api = async (path, {method='GET', body, headers={}}={}) => { const response=await fetch(path,{method,headers:{Accept:'application/json','Content-Type':'application/json',...(session?{Authorization:`Bearer ${session.access_token}`}:{}) ,...headers},body:body?JSON.stringify(body):undefined,credentials:'same-origin'}); let data={}; try{data=await response.json()}catch{} if(!response.ok || data.success===false){throw new Error(data?.error?.message||data?.message||`Request failed (${response.status})`)} return data.data; };
    const saveSession = data => { session={...data,stored_at:Date.now()};sessionStorage.setItem(STORE,JSON.stringify(session)); };
    const show = name => { $('#landing').classList.toggle('hidden',name!=='landing');$('#auth').classList.toggle('hidden',name!=='auth');$('#portal').classList.toggle('hidden',name!=='portal');$('#signout').classList.toggle('hidden',!session); if(name==='portal') loadView(currentView); };
    const showRegistration = (step, payload={}) => { registration={...registration,step,...payload}; sessionStorage.setItem(REG,JSON.stringify(registration)); $('#login-panel').classList.add('hidden');$('#register-panel').classList.add('hidden');$('#registration-flow').classList.remove('hidden'); const map={email:['Email verification','Verify your email.','Enter the code sent to your email address.','Email code','Verify email'],whatsapp:['WhatsApp verification','Verify your WhatsApp number.','Enter the six-digit code sent to your WhatsApp number.','WhatsApp code','Verify WhatsApp'],totp:['Authenticator setup','Protect your account.','Scan this QR code using an authenticator app, then enter its current six-digit code.','Authenticator code','Activate account']}; const item=map[step]; $('#registration-step').textContent=item[0];$('#registration-title').textContent=item[1];$('#registration-copy').textContent=item[2];$('#verification-label').textContent=item[3];$('#verification-submit').textContent=item[4]; $('#totp-qr').classList.toggle('hidden',step!=='totp'); if(step==='totp')$('#totp-qr').src=registration.qr_code_data_uri||''; };
    const viewRegistration = () => registration ? showRegistration(registration.step) : null;
    $$('.hero [data-screen]').forEach(button=>button.addEventListener('click',()=>{show('auth'); if(button.dataset.screen==='login'){$('#register-panel').classList.add('hidden')} else {$('#login-panel').classList.add('hidden')} viewRegistration();}));
    $('#register-form').addEventListener('submit',async event=>{event.preventDefault(); const data=Object.fromEntries(new FormData(event.currentTarget)); try{const result=await api('/api/v1/auth/register/start',{method:'POST',body:data}); registration={registration_id:result.registration_id,registration_token:result.registration_token,step:'email'};showRegistration('email');setMessage('A verification code was sent to your email address.','success');}catch(error){setMessage(error.message,'error')}});
    $('#verification-form').addEventListener('submit',async event=>{event.preventDefault(); if(!registration)return;const code=$('#verification-code').value.trim();try{if(registration.step==='email'){await api('/api/v1/auth/register/email/verify',{method:'POST',body:{...registration,otp_code:code}});showRegistration('whatsapp')}else if(registration.step==='whatsapp'){await api('/api/v1/auth/register/whatsapp/verify',{method:'POST',body:{...registration,otp_code:code}});const setup=await api('/api/v1/auth/register/totp/setup',{method:'POST',body:registration});showRegistration('totp',{qr_code_data_uri:setup.qr_code_data_uri})}else{await api('/api/v1/auth/register/totp/confirm',{method:'POST',body:{...registration,totp_code:code}});sessionStorage.removeItem(REG);registration=null;$('#registration-flow').classList.add('hidden');$('#login-panel').classList.remove('hidden');setMessage('Your account is active. Sign in with your authenticator code.','success')}}catch(error){setMessage(error.message,'error')}});
    $('#verification-resend').addEventListener('click',async()=>{if(!registration)return;const endpoint=registration.step==='email'?'/api/v1/auth/register/email/resend':'/api/v1/auth/register/whatsapp/resend';try{await api(endpoint,{method:'POST',body:registration});setMessage('A new verification code was requested.','success')}catch(error){setMessage(error.message,'error')}});
    $('#login-form').addEventListener('submit',async event=>{event.preventDefault(); const values=Object.fromEntries(new FormData(event.currentTarget)); const payload={email:values.email,password:values.password,installation_id:installId(),platform:'WEB',device_name:navigator.userAgent.slice(0,140),device_model:navigator.platform||'Web browser',os_version:navigator.userAgent.slice(0,90),app_version:'portal-1.0.0',[values.mfa_type]:values.mfa};try{const result=await api('/api/v1/auth/login',{method:'POST',body:payload});saveSession(result);show('portal');setMessage('Secure session established.','success')}catch(error){setMessage(error.message,'error')}});
    $('#signout').addEventListener('click',()=>{sessionStorage.removeItem(STORE);session=null;show('landing');});
    $$('.side button').forEach(button=>button.addEventListener('click',()=>{currentView=button.dataset.view;$$('.side button').forEach(b=>b.classList.toggle('active',b===button));loadView(currentView)}));
    const card = (title, body, action='') => `<article class="item"><h3>${escape(title)}</h3><p>${escape(body||'')}</p>${action?`<div class="actions">${action}</div>`:''}</article>`;
    const loadView = async view => { const content=$('#portal-content');content.classList.add('loading');content.innerHTML='<p class="empty">Loading current account data…</p>';try{if(view==='overview'){const data=await api('/api/v1/dashboard');const a=data.account||{};const l=data.learning||{};content.innerHTML=`<div class="eyebrow">Account overview</div><h2>Welcome, ${escape(a.name||session?.user?.name||'Trader')}.</h2><div class="data-grid"><div class="metric"><span>Account</span><strong>${escape(a.account_type||'FREE')}</strong></div><div class="metric"><span>Premium access</span><strong>${a.premium_access?'Active':'Not active'}</strong></div><div class="metric"><span>Lessons completed</span><strong>${escape(l.completed_lessons??0)}</strong></div></div><div class="notice">Your dashboard is loaded directly from the TradeX database. Access and payments are verified server-side.</div>`}else if(view==='learning'){const data=await api('/api/v1/education/courses');const items=data.items||[];content.innerHTML=`<div class="eyebrow">Education</div><h2>My learning</h2><div class="course-list">${items.length?items.map(course=>card(course.title||course.name||'Course',course.description||course.access_message||course.access_level||'',`<button data-course="${escape(course.uuid||'')}">Open course</button>`)).join(''):'<p class="empty">No published courses are available for this account yet.</p>'}</div>`;$$('[data-course]',content).forEach(button=>button.addEventListener('click',()=>openCourse(button.dataset.course)))}else if(view==='purchase'){const data=await api('/api/v1/payments/methods');const methods=data.methods||[];content.innerHTML=`<div class="eyebrow">Access</div><h2>${escape(data.product?.name||'Education Premium')}</h2><p>${data.purchase_allowed?'Choose an available secure payment method.':'Your current account does not need a new premium purchase.'}</p><div class="method-list">${methods.map(method=>card(method.display_name,method.available?`${method.amount?.amount||''} ${method.amount?.currency||''}`:`Unavailable: ${method.unavailable_reason||'not configured'}`,method.available?`<button class="primary" data-pay="${escape(method.code)}">Continue with ${escape(method.display_name)}</button>`:'')).join('')}</div>`;$$('[data-pay]',content).forEach(button=>button.addEventListener('click',()=>startPayment(button.dataset.pay)))}else{const data=await api('/api/v1/copy-trade/brokers');const brokers=data.brokers||[];content.innerHTML=`<div class="eyebrow">Copy trading</div><h2>Broker onboarding</h2><p>Open an eligible partner account through TradeX first, then submit its account number for verification.</p><div class="broker-list">${brokers.map(item=>card(item.broker_name||item.name||'Broker',item.market_category||item.description||'',`<button data-broker="${escape(item.uuid||'')}">Open partner account</button>`)).join('')||'<p class="empty">No broker onboarding options are currently available.</p>'}</div>`;$$('[data-broker]',content).forEach(button=>button.addEventListener('click',()=>openBroker(button.dataset.broker)))} }catch(error){content.innerHTML=`<div class="notice error">${escape(error.message)}</div>`}finally{content.classList.remove('loading')}};
    const openCourse = async id => {if(!id)return;try{const data=await api(`/api/v1/education/courses/${encodeURIComponent(id)}`);const course=data.course||{};$('#portal-content').innerHTML=`<div class="eyebrow">Course</div><h2>${escape(course.title||course.name||'Course')}</h2><div class="course-list">${(data.modules||[]).map(module=>card(module.title||module.name||'Module',`${(module.lessons||[]).length} lesson(s)`)).join('')||'<p class="empty">No published modules are available.</p>'}</div>`}catch(error){setMessage(error.message,'error')}};
    const startPayment = async provider => {try{const endpoints={STRIPE:'/api/v1/payments/stripe/checkout-sessions',NOWPAYMENTS:'/api/v1/payments/nowpayments/invoices',PAYPAL:'/api/v1/payments/paypal/orders'};const endpoint=endpoints[provider];if(!endpoint)throw new Error('This payment method requires the secure manual payment workflow.');const order=await api(endpoint,{method:'POST',headers:{'Idempotency-Key':`web-${uuid()}`}});if(!order.approval_url)throw new Error('The payment provider did not return a secure checkout address.');window.location.assign(order.approval_url)}catch(error){setMessage(error.message,'error')}};
    const openBroker = async id => {try{const result=await api(`/api/v1/copy-trade/broker-markets/${encodeURIComponent(id)}/open-account-action`,{method:'POST'});if(!result.open_account_via_tradex_url)throw new Error(result.notice||'The selected broker is unavailable.');sessionStorage.setItem('tradex.client.broker-intent',JSON.stringify(result));window.open(result.open_account_via_tradex_url,'_blank','noopener')}catch(error){setMessage(error.message,'error')}};
    if(session)show('portal'); else show('landing'); if(registration){show('auth');showRegistration(registration.step)};
})();
</script>
</body>
</html>
